import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"48、【井】 巽下坎上","description":"周易尚氏學 - 48、【井】 巽下坎上","frontmatter":{"title":"48、【井】 巽下坎上","description":"周易尚氏學 - 48、【井】 巽下坎上"},"headers":[],"relativePath":"classics/shangshi/053.md","filePath":"classics/shangshi/053.md"}'),s={name:"classics/shangshi/053.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_48、【井】-巽下坎上" tabindex="-1">48、【井】 巽下坎上 <a class="header-anchor" href="#_48、【井】-巽下坎上" aria-label="Permalink to “48、【井】 巽下坎上”">​</a></h1><p>水在澤下 澤竭故困。水在澤中。汲之不窮。故兌為並。易林復之旅雲。井沸釜鳴。以旅互兌為井。鄭玄以巽木為桔槔。汲水以取並象。格槔焉有在井下者乎。兌為井。坤為邑。泰初往坤中。故改邑。二至四仍兌。與泰體同。故不改井。不改故無喪得。初至四正反兌。故曰往來井井。易林益之萃雲。往來井井。即以蘋三至上正反兌。為往來井井。荀雲。訖竟也。訖至者。言更（左絲）系至並底而盡也。繘綆也。亦未繘者。言巽繩在下。尚未繘瓶使上也。其以訖為幾。渭瓶幾至井口而覆者非也。經明曰未繘。若至井口。則已繘矣。中爻離為瓶。正當毀折之地。而巽為繩。故曰羸。羸累通。井羸其瓶者。言瓶為井甃所拘羸鉤掛也。瓶既為井所掛礙。非覆即破。故兇。揚子云酒箴雲。子猶瓶矣。居井之湄。不得左右。牽於纏徵。一旦f？ 礙。為裳所車（右3田）。注f？縣也。g？並以磚為甃也。車（右3田）系也。言瓶縣為井磚所掛礙。而瓶受系也。是揚子讀並羸其瓶。井不屬上讀。後荀爽襲子云。亦以井屬下讀。其以繘井為名者。則下文之羸其瓶。莫詳其故矣。非也。贏易林家人之頤雲。長股贏戶。長股即簫（左蟲）蛸。贏戶者。言以比絲纏繞於戶上也。是以贏為累。故荀訓為拘贏。虞釋為鈞贏。他若陸績蜀才作累。王肅作縹。王肅作縲。其字雖異。其音皆同。其義如一。</p><p>彖曰。巽乎水而上水。井。井養而不窮也。改己不改井。乃以剛中也。訖王亦未繘。來有功也。井羸其瓶。是以兇也。</p><p>句依荀讀。故汲古閣所刊李氏集解。及雅麗堂刊本。皆井字屬下。坎在上故曰上水。巽人也。巽乎水而上水。言以瓶人水。汲水使上也。水所以養人。取之不竭。故養而不窮。二五皆剛。故不改。未繘故無功。井拘累其瓶使水覆。故兇。訖至亦未簫（左蟲）。荀注云汽竟也。繘所以出水通井。今居初未得應五。故未繘也。不與井連文。井羸其瓶。荀注云。井謂二。瓶謂初。初欲應五。為二所拘羸。以井屬下讀。與揚子同。故從之。</p><p>象曰。木上有水。井。君子以勞民勸相。</p><p>坎為眾為民為勞卦。故曰勞民。釋詁相導也。兌為言。故曰勸相。言以言語勸導。使有所勉也。</p><p>初六。井泥不食。舊井無禽。</p><p>初在井下。故曰泥。兌口為食。兌覆故不食。並原以汲水。今無水而泥。其為舊井無疑也。禽獲也。無水故無所得。其以禽鳥為詁者非。又按舊井者廢井也。兌為井。兌覆為巽。故井廢。</p><h3 id="象曰。井泥不食。下也。舊井無禽。時舍也。" tabindex="-1">象曰。井泥不食。下也。舊井無禽。時舍也。 <a class="header-anchor" href="#象曰。井泥不食。下也。舊井無禽。時舍也。" aria-label="Permalink to “象曰。井泥不食。下也。舊井無禽。時舍也。”">​</a></h3><p>舍。棄也。</p><p>九二。井谷射鮒，甕敝漏。</p><p>二後兌體之下。故曰並谷。巽為魚。故曰鮒。子夏傳蝦h？ 也。伏震為射。蝦g？穴居水際。故曰並谷射鮒。伏震為雍（下瓦）。巽下缺。雍（下瓦）無當。故敝漏。夫井內之穴。井矢所能加。雍（下瓦）漏則水洩。而失其用。以二前遇陽。應亦陽。故動靜皆不適也。</p><h3 id="象曰。井谷射鮒-無與也。" tabindex="-1">象曰。井谷射鮒，無與也。 <a class="header-anchor" href="#象曰。井谷射鮒-無與也。" aria-label="Permalink to “象曰。井谷射鮒，無與也。”">​</a></h3><p>言五元應與。</p><p>九三。井渫不食，為我心惻。可用汲，王明，並受其福。</p><p>三應在上。上居坎水上。故曰井渫。漢書王莽傳。潰（左示）毛（左目）不渫。注渫徹也。通出。揚子方言。渫歇也。茲曰井渫。謂井水渾蜀沉歇而清徹也。初為促則上為渫。正上居坎水上之象也。夫水潔（左無）宜食矣。乃竟不食者。以五亦陽為阻三不得應上也。兌為食。為使也。坎為心為憂。為我心惻者。言三被阻。不能汲上。使我心優也。然三與上究為正應。上水既渫而清。三僅可汲。五豈能終阻之。王謂五。五坎為隱伏。故不明。然王終有明時。王明則三上汲引。養而不窮。天下普受其福矣。凡爻有正應者。初雖有阻。終必相合。同人九五曰。先號眺（左口）而後笑。大師克相遇。言五克去三四之阻。終能遇二也。漸九五曰。終莫之勝吉。得所願也。盲五終能勝三。與二相合也。茲害三者五。五君位尊。三不敢言克言勝。只冀王明而已。王明則三上終相遇也。文王服事忠誠。情見乎辭。因五為阻。故呼王明。舊解不知不食之故。在五敵為阻。又不知王明並受其福。即言三上終能應與。特以五而變其辭耳。故無一得解者。</p><h3 id="象曰。井渫不食-行惻也。求王明-受福也。" tabindex="-1">象曰。井渫不食，行惻也。求王明，受福也。 <a class="header-anchor" href="#象曰。井渫不食-行惻也。求王明-受福也。" aria-label="Permalink to “象曰。井渫不食，行惻也。求王明，受福也。”">​</a></h3><p>不食之故，其咎在五。故曰求王明。</p><p>六四。井甃,無咎。</p><p>以瓦甓砌井曰甃。兌為井。六四居兌上。則井將修成。故無咎。</p><h3 id="象日。井甃無咎。修井也。" tabindex="-1">象日。井甃無咎。修井也。 <a class="header-anchor" href="#象日。井甃無咎。修井也。" aria-label="Permalink to “象日。井甃無咎。修井也。”">​</a></h3><p>甃修也。</p><p>九五。井冽，寒泉食。</p><p>冽甘也。坎為寒為泉。泉既甘冽。故可食。</p><h3 id="象曰。寒泉之食。中正也。" tabindex="-1">象曰。寒泉之食。中正也。 <a class="header-anchor" href="#象曰。寒泉之食。中正也。" aria-label="Permalink to “象曰。寒泉之食。中正也。”">​</a></h3><p>五雖無應。然位正中。故可食</p><p>上六、井收勿幕。有孚元吉。</p><p>收成也。幕蓋也。覆也。坎為隱伏。故為蓋覆。六居坎上故勿幕。言井既成。以出水為功。不宜蓋覆也。 三得陽應。故有孚而吉。</p><h3 id="象曰。元吉在上。大成也。" tabindex="-1">象曰。元吉在上。大成也。 <a class="header-anchor" href="#象曰。元吉在上。大成也。" aria-label="Permalink to “象曰。元吉在上。大成也。”">​</a></h3><p>成即收也。</p>',30)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
